// Colour grading maths: a line-by-line port of backend/app/grade.py (point operations, effect
// resolution, .cube parsing). Checked against shared/grade_cases.json, which is generated by the
// Python implementation. Both sides bake the point operations into the same 33^3 LUT.
import presetsJson from "../../../shared/presets.json";
import type { Filter } from "../types";

export type RGB = [number, number, number];
export interface Cube { size: number; min: RGB; max: RGB; table: Float32Array } // [b][g][r] x 3

export interface PresetDef {
  label: string;
  adjust?: Record<string, number>;
  split?: { shadows?: number[]; highlights?: number[] };
  fade?: number;
  mono?: boolean;
  effects?: Record<string, Record<string, number>>;
}
export const PRESETS = presetsJson.presets as unknown as Record<string, PresetDef>;
export const VHS = presetsJson.vhs as unknown as PresetDef & { chroma: number };
export const PRESET_ORDER = Object.keys(PRESETS);

export const LUT_SIZE = 33;
export const GRAIN_FRAMES = 8;
export const ADJUST_KEYS = ["exposure", "temperature", "tint", "brightness", "contrast", "highlights", "shadows",
  "whites", "blacks", "saturation", "vibrance", "sharpen", "blur"] as const;
const COLOR_KEYS = ADJUST_KEYS.slice(0, 11);
export const EFFECT_KEYS = ["grain", "vignette", "lightleak", "vhs", "glow", "chroma"] as const;
export type EffectKey = (typeof EFFECT_KEYS)[number];
export const EFFECT_DEFAULTS: Record<EffectKey, Record<string, number>> = {
  grain: { amount: 0, size: 1.5 },
  vignette: { amount: 0, feather: 0.5 },
  lightleak: { amount: 0, speed: 0.35 },
  vhs: { amount: 0 },
  glow: { amount: 0, threshold: 0.7, radius: 14 },
  chroma: { amount: 0 },
};

const LUMA: RGB = [0.2126, 0.7152, 0.0722];
const MONO: RGB = [0.3, 0.59, 0.11];
const clamp01 = (x: number) => Math.min(1, Math.max(0, x));
export const smoothstep = (e0: number, e1: number, x: number) => {
  const t = clamp01((x - e0) / (e1 - e0));
  return t * t * (3 - 2 * t);
};
const luma = (c: RGB) => c[0] * LUMA[0] + c[1] * LUMA[1] + c[2] * LUMA[2];

export function adjust(c: RGB, p: Record<string, number | undefined>): RGB {
  const g = (k: string) => Number(p[k] ?? 0) || 0;
  let [r, gr, b] = c;
  const e = g("exposure"), T = g("temperature") / 100, Ti = g("tint") / 100;
  if (e || T || Ti) {
    const m = 2 ** e;
    const lin = [Math.max(0, r) ** 2.2 * m * (1 + 0.15 * T), Math.max(0, gr) ** 2.2 * m * (1 - 0.12 * Ti), Math.max(0, b) ** 2.2 * m * (1 - 0.15 * T)];
    [r, gr, b] = lin.map((v) => Math.max(0, v) ** (1 / 2.2));
  }
  const B = g("brightness") / 100;
  if (B) { r += 0.15 * B; gr += 0.15 * B; b += 0.15 * B; }
  const C = g("contrast") / 100;
  if (C) {
    const k = C >= 0 ? 1 + 0.8 * C : 1 + 0.6 * C;
    r = (r - 0.5) * k + 0.5; gr = (gr - 0.5) * k + 0.5; b = (b - 0.5) * k + 0.5;
  }
  const sh = g("shadows") / 100, hi = g("highlights") / 100, bl = g("blacks") / 100, wh = g("whites") / 100;
  if (sh || hi || bl || wh) {
    const Y = luma([r, gr, b]);
    const d = 0.25 * sh * (1 - smoothstep(0, 0.6, Y)) + 0.25 * hi * smoothstep(0.4, 1, Y)
      + 0.12 * bl * (1 - smoothstep(0, 0.25, Y)) + 0.12 * wh * smoothstep(0.75, 1, Y);
    r += d; gr += d; b += d;
  }
  const S = g("saturation") / 100, V = g("vibrance") / 100;
  if (S || V) {
    const Y = luma([r, gr, b]);
    const m = clamp01(Math.max(r, gr, b) - Math.min(r, gr, b));
    const f = Math.max(0, 1 + S + V * (1 - m));
    r = Y + (r - Y) * f; gr = Y + (gr - Y) * f; b = Y + (b - Y) * f;
  }
  return [clamp01(r), clamp01(gr), clamp01(b)];
}

export function presetColor(c: RGB, d: PresetDef): RGB {
  let x = adjust(c, d.adjust ?? {});
  if (d.split) {
    const Y = luma(x);
    const ws = 1 - smoothstep(0, 0.6, Y), wh = smoothstep(0.4, 1, Y);
    const s = d.split.shadows ?? [0, 0, 0], h = d.split.highlights ?? [0, 0, 0];
    x = [x[0] + s[0] * ws + h[0] * wh, x[1] + s[1] * ws + h[1] * wh, x[2] + s[2] * ws + h[2] * wh];
  }
  const f = Number(d.fade ?? 0);
  if (f) x = [f + x[0] * (1 - f), f + x[1] * (1 - f), f + x[2] * (1 - f)];
  if (d.mono) {
    const y = clamp01(x[0]) * MONO[0] + clamp01(x[1]) * MONO[1] + clamp01(x[2]) * MONO[2];
    x = [y, y, y];
  }
  return [clamp01(x[0]), clamp01(x[1]), clamp01(x[2])];
}

export function skinWeight(c: RGB): number {
  const [r, g, b] = c;
  const v = Math.max(r, g, b), mn = Math.min(r, g, b), d = v - mn;
  const s = v > 1e-6 ? d / Math.max(v, 1e-6) : 0;
  const dd = Math.max(d, 1e-6);
  let h = v === r ? ((((g - b) / dd) % 6) + 6) % 6 : v === g ? (b - r) / dd + 2 : (r - g) / dd + 4;
  h *= 60;
  if (d < 1e-6) h = 0;
  let dh = Math.abs(h - 18);
  dh = Math.min(dh, 360 - dh);
  const wh = 1 - smoothstep(20, 40, dh);
  const ws = smoothstep(0.08, 0.18, s) * (1 - smoothstep(0.65, 0.85, s));
  const wv = smoothstep(0.12, 0.3, v);
  return wh * ws * wv;
}

export function protectSkin(orig: RGB, graded: RGB): RGB {
  const w = 0.85 * skinWeight(orig);
  const k = luma(graded) / Math.max(luma(orig), 1e-4);
  return [0, 1, 2].map((i) => graded[i] * (1 - w) + clamp01(orig[i] * k) * w) as RGB;
}

export function sampleCube(cube: Cube, c: RGB): RGB {
  const n = cube.size, t = cube.table;
  const x = [0, 1, 2].map((i) => clamp01((c[i] - cube.min[i]) / (cube.max[i] - cube.min[i])) * (n - 1));
  const i0 = x.map((v) => Math.min(n - 2, Math.max(0, Math.floor(v))));
  const f = x.map((v, i) => v - i0[i]);
  const at = (db: number, dg: number, dr: number, ch: number) => t[(((i0[2] + db) * n + (i0[1] + dg)) * n + (i0[0] + dr)) * 3 + ch];
  const out: RGB = [0, 0, 0];
  for (let ch = 0; ch < 3; ch++) {
    const c00 = at(0, 0, 0, ch) * (1 - f[0]) + at(0, 0, 1, ch) * f[0];
    const c01 = at(0, 1, 0, ch) * (1 - f[0]) + at(0, 1, 1, ch) * f[0];
    const c10 = at(1, 0, 0, ch) * (1 - f[0]) + at(1, 0, 1, ch) * f[0];
    const c11 = at(1, 1, 0, ch) * (1 - f[0]) + at(1, 1, 1, ch) * f[0];
    out[ch] = (c00 * (1 - f[1]) + c01 * f[1]) * (1 - f[2]) + (c10 * (1 - f[1]) + c11 * f[1]) * f[2];
  }
  return out;
}

type F = Pick<Filter, "type" | "name" | "intensity" | "params" | "enabled">;
const on = (f: F) => f.enabled !== false;
const prm = (f: F) => (f.params ?? {}) as Record<string, unknown>;

export function gradeColor(c0: RGB, filters: F[], cubes: Record<string, Cube>): RGB {
  let c = c0;
  const act = filters.filter(on);
  for (const f of act) if (f.type === "adjust") c = adjust(c, prm(f) as Record<string, number>);
  for (const f of act) {
    if (f.type !== "preset" && f.type !== "lut") continue;
    const I = Number(f.intensity ?? 1);
    if (I <= 0) continue;
    let graded: RGB;
    if (f.type === "preset") {
      const d = PRESETS[f.name ?? ""];
      if (!d) continue;
      graded = presetColor(c, d);
    } else {
      const cube = cubes[String(prm(f).lut ?? "")];
      if (!cube) continue;
      graded = sampleCube(cube, c).map(clamp01) as RGB;
    }
    // Skin protection never applies to monochrome presets (B&W is meant to be grey).
    const mono = f.type === "preset" && !!PRESETS[f.name ?? ""]?.mono;
    if (prm(f).skinProtect !== false && !mono) graded = protectSkin(c, graded);
    c = [c[0] + (graded[0] - c[0]) * I, c[1] + (graded[1] - c[1]) * I, c[2] + (graded[2] - c[2]) * I];
  }
  const vhs = effects(filters).vhs.amount;
  if (vhs > 0) {
    const v = presetColor(c, VHS);
    c = [c[0] + (v[0] - c[0]) * vhs, c[1] + (v[1] - c[1]) * vhs, c[2] + (v[2] - c[2]) * vhs];
  }
  return [clamp01(c[0]), clamp01(c[1]), clamp01(c[2])];
}

export function effects(filters: F[]): Record<EffectKey, Record<string, number>> {
  const out = Object.fromEntries(EFFECT_KEYS.map((k) => [k, { ...EFFECT_DEFAULTS[k] }])) as Record<EffectKey, Record<string, number>>;
  const merge = (name: string, p: Record<string, unknown>, I: number) => {
    const e = out[name as EffectKey];
    if (!e) return;
    e.amount = Math.min(1, e.amount + Number(p.amount ?? 0) * I);
    for (const [k, v] of Object.entries(p)) if (k !== "amount") e[k] = Number(v);
  };
  for (const f of filters) {
    if (!on(f)) continue;
    if (f.type === "effect") merge(f.name ?? "", prm(f), Number(f.intensity ?? 1));
    else if (f.type === "preset") {
      const d = PRESETS[f.name ?? ""];
      for (const [name, p] of Object.entries(d?.effects ?? {})) merge(name, p, Number(f.intensity ?? 1));
    }
  }
  return out;
}

export function adjustParams(filters: F[]): Record<string, number> {
  const f = filters.find((x) => x.type === "adjust" && on(x));
  return (f ? prm(f) : {}) as Record<string, number>;
}

export function hasColor(filters: F[]): boolean {
  for (const f of filters) {
    if (!on(f)) continue;
    if (f.type === "adjust" && COLOR_KEYS.some((k) => Number(prm(f)[k] ?? 0))) return true;
    if ((f.type === "preset" || f.type === "lut") && Number(f.intensity ?? 1) > 0) return true;
  }
  return effects(filters).vhs.amount > 0;
}

export function needsGrade(filters: F[] | undefined): boolean {
  if (!filters?.length) return false;
  const p = adjustParams(filters);
  const fx = effects(filters);
  return hasColor(filters) || Number(p.sharpen ?? 0) > 0 || Number(p.blur ?? 0) > 0 || EFFECT_KEYS.some((k) => fx[k].amount > 0);
}

/** (n^3) RGB float LUT, index r + g*n + b*n*n (the .cube order). */
export function buildLut(filters: F[], cubes: Record<string, Cube>, n = LUT_SIZE): Float32Array {
  const out = new Float32Array(n * n * n * 3);
  let i = 0;
  for (let b = 0; b < n; b++)
    for (let g = 0; g < n; g++)
      for (let r = 0; r < n; r++) {
        const c = gradeColor([r / (n - 1), g / (n - 1), b / (n - 1)], filters, cubes);
        out[i++] = c[0]; out[i++] = c[1]; out[i++] = c[2];
      }
  return out;
}

export function parseCube(text: string): Cube {
  let size = 0;
  let min: RGB = [0, 0, 0], max: RGB = [1, 1, 1];
  const rows: number[] = [];
  for (const line of text.split(/\r?\n/)) {
    const s = line.trim();
    if (!s || s.startsWith("#")) continue;
    const parts = s.split(/\s+/);
    const key = parts[0].toUpperCase();
    if (key === "LUT_3D_SIZE") size = parseInt(parts[1], 10);
    else if (key === "LUT_1D_SIZE") throw new Error("1D LUTs are not supported; use a 3D .cube LUT.");
    else if (key === "DOMAIN_MIN") min = parts.slice(1, 4).map(Number) as RGB;
    else if (key === "DOMAIN_MAX") max = parts.slice(1, 4).map(Number) as RGB;
    else if (/^[A-Z_]+$/.test(key)) continue;
    else rows.push(Number(parts[0]), Number(parts[1]), Number(parts[2]));
  }
  if (!(size >= 2 && size <= 128)) throw new Error("Missing or invalid LUT_3D_SIZE.");
  if (rows.length !== size ** 3 * 3) throw new Error(`Expected ${size ** 3} table rows, found ${rows.length / 3}.`);
  return { size, min, max, table: Float32Array.from(rows) };
}

// Spatial effect formulas shared with grade.py.
export const vignetteValue = (u: number, v: number, amount: number, feather: number) => {
  const d = Math.hypot(u - 0.5, v - 0.5) / 0.70710678;
  const r0 = 0.25 + 0.4 * (1 - feather);
  return 1 - amount * smoothstep(r0, r0 + 0.3 + 0.5 * feather, d);
};
export const refScale = (W: number, H: number) => Math.min(W, H) / 1080;
